    // S237. The pattern is a label of a switch statement.
    public static Cell<int> GetterInASwitchStatement() =>
        Cell.Loop<int>().WithoutCaptures(l =>
        {
            PatternRow row = new(l.Map(v => v));
            int x;

            switch (row)
            {
                case { Now: > 0 }:
                    x = 1;
                    break;
                default:
                    x = 0;
                    break;
            }

            return S.Hold(x);
        });

