        Cell.Loop<int>().WithoutCaptures(l =>
        {
            int count = TwoItems()
                .SortBy(
                    selector: (_, state) => state,
                    sortComparer: new ReadingComparer(Plain),
                    keyComparer: Comparer<int>.Default,
                    isDescending: false)
                .KeysCell.Sample().Count;

            return S.Snapshot(l, (a, b) => a + b + count).Hold(0);
        });

