        Cell.Loop<int>().WithoutCaptures(l => { List<List<Cell<int>>> rows = [new(), new()]; rows.Fresh().Add(l.Map(v => v)); return S.Hold(rows[0].Count == 0 ? Plain.Sample() : rows[0][0].Sample()); });

