        Cell.Loop<int>().WithoutCaptures(l => { List<List<Cell<int>>> rows = [new(), new()]; foreach (List<Cell<int>> row in rows) { row.Add(l.Map(v => v)); return S.Hold(row[0].Sample()); } return S.Hold(0); });

