    public static Cell<int> QueryExpressionSelectsAnAnonymousObject() =>
        Cell.Loop<int>().WithoutCaptures(l => { var list = (from i in new[] { 0 } select new { Share = l.Map(v => v) }).ToList(); return S.Hold(list[0].Share.Sample()); });

