    public static Cell<int> SelectClauseSamplesItsRangeVariable() =>
        Cell.Loop<int>().WithoutCaptures(l => { List<Cell<int>> cells = [l.Map(v => v)]; return S.Hold((from c in cells select c.Sample()).ToList().Count); });

