    public static Cell<int> SecondFromClauseSamplesItsRangeVariable() =>
        Cell.Loop<int>().WithoutCaptures(l => { List<Cell<int>> cells = [l.Map(v => v)]; return S.Hold((from i in new[] { 0 } from c in cells select c.Sample()).ToList().Count); });

