    public static Cell<int> CalleeReadsWhatTheTurnBeforeGave() =>
        Cell.Loop<int>().WithoutCaptures(l => { Cell<int>? last = null; for (int i = 0; i < 2; i++) { SampleIfAny(last); last = l.Map(v => v); } return S.Hold(0); });

