        Cell.Loop<int>().WithoutCaptures(l => { Cell<int>? last = null; for (int j = 0; j < 2; j++) { for (int i = 0; i < 1; i++) { if (last != null) { Kept.Add(last.Sample()); } } last = l.Map(v => v); } return S.Hold(0); });

