        Cell.Loop<int>().WithoutCaptures(l => { SettableSlot x = new() { Share = l.Map(v => v) }; ISlotLine line = NewSlotLine(); line.Put(x); x.Share = Plain; Kept.Add(line.Last().Share!.Sample()); return S.Hold(0); });

