    public sealed class PatternRow(Cell<int> share) : IPatternRow
    {
        public Cell<int> Share { get; } = share;

        public int Now => this.Share.Sample();

        public bool OtherIsBig(PatternRow other) => other is { Now: > 0 };
    }

