    private static int CountOf<T>(IEnumerable<T> values)
    {
        int n = 0;

        foreach (T _ in values)
        {
            n++;
        }

        return n;
    }

    private static int CountAs<T>(T values)
        where T : IEnumerable<int>
    {
        int n = 0;

        foreach (int value in values)
        {
            n += value;
        }

        return n;
    }

