file static class Helpers
{
    public static void Add(this Shapes.Ag72Bare bare, Cell<int> c) => bare.Put(c, c.Sample());

    public static Shapes.IAg59Keeper Ag59MakeBehindBeside<T>(this Shapes.SettableSlot slot)
        where T : Shapes.IAg59Keeper, new()
    {
        slot.Share ??= Cell.Constant(6);

        return new T();
    }

    public static T Ag59MakeBeside<T>(this Shapes.SettableSlot slot)
        where T : new()
    {
        slot.Share ??= Cell.Constant(5);

        return new T();
    }

    public static void Ag60MakePlainByExtension(this Shapes.SettableSlot slot) => slot.Share = Cell.Constant(4);

    public static T Fresh<T>(this List<T> all)
        where T : new()
    {
        all.TrimExcess();

        return new T();
    }

    public static int Count(this List<Shapes.Marked> all)
    {
        all.Reverse();

        return all.Count;
    }

    public static Shapes.Marked First(this List<Shapes.Marked> all)
    {
        all.Reverse();

        return all[0];
    }

    public static void AddOne(this List<Cell<int>> cells, Cell<int> one) => cells.Add(one);

    public static Stream<T> SwitchCWithDeferredValues<T>(this Cell<Cell<T>> cca) =>
        Operational.Defer(cca.SwitchC().Values());
}
